func newComputersInventoryFilevaultCmd(ctx *registry.CLIContext) *cobra.Command {
	var (
		flagPage     int
		flagPageSize int
		flagAll      bool
		flagLimit    int
	)

	cmd := &cobra.Command{
		Use:         "filevault",
		Short:       "Return paginated FileVault information for all computers",
		Long:        "Return paginated FileVault information for all computers",
		Annotations: map[string]string{"jamf:privileges": "View Disk Encryption Recovery Key"},
		RunE: func(cmd *cobra.Command, args []string) error {
			reqCtx := cmd.Context()

			// Build request path
			path := "/v3/computers-inventory/filevault"

			// Build query string
			var queryParts []string
			if flagPage != 0 {
				queryParts = append(queryParts, fmt.Sprintf("page=%d", flagPage))
			}
			if flagPageSize != 0 {
				queryParts = append(queryParts, fmt.Sprintf("page-size=%d", flagPageSize))
			}
			if len(queryParts) > 0 {
				path = path + "?" + strings.Join(queryParts, "&")
			}

			// Auto-pagination: fetch all pages when --all is set and --page was not manually specified
			if flagAll && flagPage == 0 {
				var allResults []json.RawMessage
				prog := ctx.Output.PaginationProgress()
				defer prog.Stop()
				reqCtx = spinner.WithSuppressed(reqCtx)
				pageNum := 0
				pageSize := 100

				for {
					// Build page-specific query
					pagePath := "/v3/computers-inventory/filevault"
					var pageQuery []string
					// Carry forward non-pagination query params
					for _, qp := range queryParts {
						if !strings.HasPrefix(qp, "page=") && !strings.HasPrefix(qp, "page-size=") && !strings.HasPrefix(qp, "pagesize=") {
							pageQuery = append(pageQuery, qp)
						}
					}
					pageQuery = append(pageQuery, fmt.Sprintf("page=%d", pageNum))
					pageQuery = append(pageQuery, fmt.Sprintf("page-size=%d", pageSize))
					pagePath = pagePath + "?" + strings.Join(pageQuery, "&")

					resp, err := ctx.Client.Do(reqCtx, "GET", pagePath, nil)
					if err != nil {
						return err
					}

					body, err := io.ReadAll(resp.Body)
					resp.Body.Close()
					if err != nil {
						return err
					}

					// Parse pagination response: {"totalCount": N, "results": [...]}
					var pageResp struct {
						TotalCount int               `json:"totalCount"`
						Results    []json.RawMessage `json:"results"`
					}
					if err := json.Unmarshal(body, &pageResp); err != nil {
						// Not a paginated response; output as-is
						return ctx.Output.PrintRaw(body)
					}

					allResults = append(allResults, pageResp.Results...)
					prog.Update(len(allResults), pageResp.TotalCount)

					// Check limit
					if flagLimit > 0 && len(allResults) >= flagLimit {
						allResults = allResults[:flagLimit]
						break
					}

					// Check if we've fetched everything
					if len(pageResp.Results) < pageSize || len(allResults) >= pageResp.TotalCount {
						break
					}

					pageNum++
				}

				prog.Stop()

				// Output combined results as JSON array
				combined, err := json.MarshalIndent(allResults, "", "  ")
				if err != nil {
					return err
				}
				combined = selectTableColumns(combined, []tableColumn{
					{field: "id", label: "id"},
					{field: "general.name", label: "name"},
					{field: "hardware.serialNumber", label: "serial"},
					{field: "hardware.model", label: "model"},
					{field: "operatingSystem.version", label: "osVersion"},
					{field: "general.lastContactTime", label: "lastContactTime"},
				}, ctx.Output.Format())
				return ctx.Output.PrintRaw(combined)
			}

			// Make request
			resp, err := ctx.Client.Do(reqCtx, "GET", path, nil)
			if err != nil {
				return err
			}
			defer resp.Body.Close()

			if ctx.Output.Format() == "ndjson" {
				ndjsonBody, ndjsonErr := io.ReadAll(resp.Body)
				if ndjsonErr != nil {
					return ndjsonErr
				}
				var ndjsonWrap struct {
					Results []json.RawMessage `json:"results"`
				}
				if err := json.Unmarshal(ndjsonBody, &ndjsonWrap); err == nil && ndjsonWrap.Results != nil {
					arr, marshalErr := json.Marshal(ndjsonWrap.Results)
					if marshalErr != nil {
						return marshalErr
					}
					return ctx.Output.PrintRaw(arr)
				}
				return ctx.Output.PrintRaw(ndjsonBody)
			}
			return ctx.Output.PrintResponse(resp)
		},
	}

	cmd.Flags().IntVar(&flagPage, "page", 0, "")
	cmd.Flags().IntVar(&flagPageSize, "page-size", 100, "")
	cmd.Flags().BoolVar(&flagAll, "all", true, "Fetch all pages (set --all=false for single page)")
	cmd.Flags().IntVar(&flagLimit, "limit", 0, "Maximum total results to return (0 = unlimited)")
	return cmd
}

func newComputersInventoryUploadCmd(ctx *registry.CLIContext) *cobra.Command {
	var (
		flagFile   string
		flagName   string
		flagSerial string
		flagUdid   string
	)

	cmd := &cobra.Command{
		Use:         "upload [<id>]",
		Short:       "Upload attachment and assign to computer",
		Long:        "Upload attachment and assign to computer",
		Annotations: map[string]string{"jamf:privileges": "Update Computers"},
		Args:        cobra.MaximumNArgs(1),
		RunE: func(cmd *cobra.Command, args []string) error {
			reqCtx := cmd.Context()

			// Resolve resource ID from positional arg, --name, or lookup flags
			var resolvedID string

			if flagSerial != "" {
				noInput, _ := cmd.Flags().GetBool("no-input")
				rid, err := resolveNameToID(reqCtx, ctx.Client, "/v3/computers-inventory?section=HARDWARE", "hardware.serialNumber", "id", flagSerial, noInput)
				if err != nil {
					return fmt.Errorf("looking up --serial %q: %w", flagSerial, err)
				}
				resolvedID = rid
			} else if flagUdid != "" {
				noInput, _ := cmd.Flags().GetBool("no-input")
				rid, err := resolveNameToID(reqCtx, ctx.Client, "/v3/computers-inventory", "udid", "id", flagUdid, noInput)
				if err != nil {
					return fmt.Errorf("looking up --udid %q: %w", flagUdid, err)
				}
				resolvedID = rid
			} else if flagName != "" {
				noInput, _ := cmd.Flags().GetBool("no-input")
				rid, err := resolveNameToID(reqCtx, ctx.Client, "/v3/computers-inventory", "general.name", "id", flagName, noInput)
				if err != nil {
					return err
				}
				resolvedID = rid
			} else if len(args) > 0 {
				resolvedID = args[0]
			} else {
				return fmt.Errorf("provide an <id> argument, --name, --serial, --udid")
			}

			// Build request path
			path := "/v3/computers-inventory/{id}/attachments"
			path = strings.Replace(path, "{id}", url.PathEscape(resolvedID), 1)

			// Build query string
			var queryParts []string
			if len(queryParts) > 0 {
				path = path + "?" + strings.Join(queryParts, "&")
			}

			// Make request
			if ctx.Uploader == nil {
				return fmt.Errorf("file upload not supported in this context")
			}
			f, err := os.Open(flagFile)
			if err != nil {
				return fmt.Errorf("opening %s: %w", flagFile, err)
			}
			defer f.Close()
			// Stream the file through a seekable multipart body so Upload can
			// precompute Content-Length and retry on HTTP 429 without
			// re-buffering the file.
			body, contentType, contentLength, err := client.NewMultipartFileUpload("file", f)
			if err != nil {
				return fmt.Errorf("building multipart body: %w", err)
			}
			resp, err := ctx.Uploader.Upload(reqCtx, path, body, contentType, contentLength)
			if err != nil {
				return err
			}
			defer resp.Body.Close()

			return ctx.Output.PrintResponse(resp)
		},
	}

	cmd.Flags().StringVar(&flagFile, "file", "", "Path to file to upload (required)")
	_ = cmd.MarkFlagRequired("file")
	cmd.Flags().StringVar(&flagName, "name", "", "Look up computers-inventory by name")
	cmd.Flags().StringVar(&flagSerial, "serial", "", "Look up computer by serial number")
	cmd.Flags().StringVar(&flagUdid, "udid", "", "Look up computer by UDID")

	return cmd
}

func newComputersInventoryDownloadCmd(ctx *registry.CLIContext) *cobra.Command {
	var (
		flagSaveTo string
	)

	cmd := &cobra.Command{
		Use:   "download <id> <attachmentId>",
		Short: "Download attachment file",
		Long:  "Download attachment file",
		Example: `  # Save to file
  jamf-cli pro computers-inventory download <id> <attachmentId> -O output.bin

  # Pipe to stdout
  jamf-cli pro computers-inventory download <id> <attachmentId> > output.bin`,
		Annotations: map[string]string{"jamf:privileges": "Read Computers"},
		Args:        cobra.ExactArgs(2),
		RunE: func(cmd *cobra.Command, args []string) error {
			reqCtx := cmd.Context()
			reqCtx = registry.WithAccept(reqCtx, "*/*")

			// Build request path
			path := "/v3/computers-inventory/{id}/attachments/{attachmentId}"
			path = strings.Replace(path, "{id}", url.PathEscape(args[0]), 1)
			path = strings.Replace(path, "{attachmentId}", url.PathEscape(args[1]), 1)

			// Build query string
			var queryParts []string
			if len(queryParts) > 0 {
				path = path + "?" + strings.Join(queryParts, "&")
			}

			// Make request
			resp, err := ctx.Client.Do(reqCtx, "GET", path, nil)
			if err != nil {
				return err
			}
			defer resp.Body.Close()

			if flagSaveTo != "" {
				f, err := os.Create(flagSaveTo)
				if err != nil {
					return fmt.Errorf("opening output file: %w", err)
				}
				defer f.Close()
				n, err := io.Copy(f, resp.Body)
				if err != nil {
					return err
				}
				fmt.Fprintf(os.Stderr, "Saved to %s (%d bytes)\n", flagSaveTo, n)
				return nil
			}
			_, err = io.Copy(os.Stdout, resp.Body)
			return err
		},
	}

	cmd.Flags().StringVarP(&flagSaveTo, "save-to", "O", "", "Save output to file instead of stdout")
	return cmd
}

